import itertools


def raises(fn):
    try:
        fn()
    except Exception as e:
        return type(e).__name__
    return None


def err_msg(fn):
    try:
        fn()
    except Exception as e:
        return str(e)
    return None


def flaky(n_fail):
    state = {"n": 0}

    def f():
        state["n"] += 1
        if state["n"] <= n_fail:
            raise RuntimeError("fail")
        return "ok"

    return f


def counter_fn():
    state = {"n": 0}

    def f():
        state["n"] += 1
        return state["n"]

    return f


def memo_demo(deco):
    calls = []

    @deco
    def sq(x):
        calls.append(x)
        return x * x

    sq(2)
    sq(2)
    sq(3)
    sq(3)
    return calls


